const POKEMON = [
  {id:1,name:'Bulbasaur',types:['Grass','Poison'],desc:'Um Pokémon planta que fica mais forte enquanto toma sol. A semente em suas costas cresce com ele.',abilities:['Overgrow','Chlorophyll'],stats:{hp:45,atk:49,def:49,spa:65,spd:65,spe:45},curiosities:['Foi o primeiro Pokémon listado no Pokédex original.','É um dos únicos starters com dois tipos desde o início.','A semente em suas costas é um ser vivo simbiótico.']},
  {id:2,name:'Ivysaur',types:['Grass','Poison'],desc:'Quando o bulbo em suas costas cresce, o Pokémon parece perder a capacidade de ficar em pé.',abilities:['Overgrow','Chlorophyll'],stats:{hp:60,atk:62,def:63,spa:80,spd:80,spe:60},curiosities:['Um dos starters intermediários menos escolhidos.','O bulbo floresce com luz solar intensa.','Absorve nutrientes do solo pelo bulbo.']},
  {id:3,name:'Venusaur',types:['Grass','Poison'],desc:'A flor em suas costas captura a luz do sol. O perfume chama Pokémon e humanos.',abilities:['Overgrow','Chlorophyll'],stats:{hp:80,atk:82,def:83,spa:100,spd:100,spe:80},curiosities:['Considerado o mais equilibrado dos starters finais de Kanto.','Tem Mega Evolução com a habilidade Thick Fat.','O nome combina Venus + Saurus (lagarto).']},
  {id:4,name:'Charmander',types:['Fire'],desc:'Prefere lugares quentes. Quando chove, vapor sai da ponta de sua cauda.',abilities:['Blaze','Solar Power'],stats:{hp:39,atk:52,def:43,spa:60,spd:50,spe:65},curiosities:['A chama na cauda indica o nível de vida — se apagar, o Pokémon morre.','É o starter mais popular de Kanto entre os fãs.','Baseado em salamandras, que na lenda sobreviviam ao fogo.']},
  {id:5,name:'Charmeleon',types:['Fire'],desc:'Ao ganhar experiência, torna-se mais agressivo. O rabo ardente deixa cicatrizes.',abilities:['Blaze','Solar Power'],stats:{hp:58,atk:64,def:58,spa:80,spd:65,spe:80},curiosities:['Tem temperamento muito mais agressivo que Charmander.','Usa as garras para escalar montanhas vulcânicas.','Prefere viver perto de crateras vulcânicas.']},
  {id:6,name:'Charizard',types:['Fire','Flying'],desc:'Cospe fogo quente o suficiente para derreter pedras. Causa incêndios em florestas ao voar.',abilities:['Blaze','Solar Power'],stats:{hp:78,atk:84,def:78,spa:109,spd:85,spe:100},curiosities:['Tem duas Mega Evoluções: X (Fogo/Dragão) e Y.','Apesar da aparência, NÃO é do tipo Dragão originalmente.','Um dos Pokémon mais icônicos de toda a franquia.']},
  {id:7,name:'Squirtle',types:['Water'],desc:'Quando se retrai em sua concha, chuta água com grande força e precisão.',abilities:['Torrent','Rain Dish'],stats:{hp:44,atk:48,def:65,spa:50,spd:64,spe:43},curiosities:['A concha protege de ataques e ajuda na hidrodinâmica.','Pode retrair braços, pernas e pescoço completamente.','O ângulo da cauda em espiral diferencia cada indivíduo.']},
  {id:8,name:'Wartortle',types:['Water'],desc:'A cauda peluda indica a idade. Pokémon mais velhos têm caudas mais escuras.',abilities:['Torrent','Rain Dish'],stats:{hp:59,atk:63,def:80,spa:65,spd:80,spe:58},curiosities:['Pode viver até 10.000 anos.','As orelhas e cauda são símbolos de longevidade.','É um dos poucos Pokémon associado com boa sorte.']},
  {id:9,name:'Blastoise',types:['Water'],desc:'Os canhões em sua carapaça disparam balas de água com precisão cirúrgica.',abilities:['Torrent','Rain Dish'],stats:{hp:79,atk:83,def:100,spa:85,spd:105,spe:78},curiosities:['Os canhões podem disparar água que penetra aço.','Tem Mega Evolução com três canhões.','Símbolo de força e resistência no mundo Pokémon.']},
  {id:10,name:'Caterpie',types:['Bug'],desc:'Ao se sentir ameaçado, emite odor terrível de suas antenas para afastar inimigos.',abilities:['Shield Dust','Run Away'],stats:{hp:45,atk:30,def:35,spa:20,spd:20,spe:45},curiosities:['Come folhas da sua própria altura em um dia.','É um dos Pokémon mais fáceis de capturar.','Evolui rapidamente para Butterfree em apenas 2 estágios.']},
  {id:11,name:'Metapod',types:['Bug'],desc:'Embora pareça indefeso, a carapaça é extremamente resistente.',abilities:['Shed Skin'],stats:{hp:50,atk:20,def:55,spa:25,spd:25,spe:30},curiosities:['Praticamente só pode usar Harden no jogo.','Por dentro, o corpo está se fundindo para virar Butterfree.','A casca é tão dura que nenhum predador consegue quebrar.']},
  {id:12,name:'Butterfree',types:['Bug','Flying'],desc:'Tem asas cobertas com escamas venenosas que causam paralisia.',abilities:['Compound Eyes','Tinted Lens'],stats:{hp:60,atk:45,def:50,spa:90,spd:80,spe:70},curiosities:['Um dos primeiros Pokémon capturados por Ash.','Tem um episódio icônico onde Ash o liberta para acasalar.','As escamas das asas repelem água mesmo sob chuva.']},
  {id:13,name:'Weedle',types:['Bug','Poison'],desc:'Possui ferrão de veneno de 2 cm no topo da cabeça. Vive em florestas.',abilities:['Shield Dust','Run Away'],stats:{hp:40,atk:35,def:30,spa:20,spd:20,spe:50},curiosities:['Come folhas equivalentes ao seu peso todo dia.','O ferrão defende de pássaros predadores.','É o equivalente ao Caterpie do lado do Team Rocket.']},
  {id:14,name:'Kakuna',types:['Bug','Poison'],desc:'Quase incapaz de se mover, segrega toxina da pele para se proteger.',abilities:['Shed Skin'],stats:{hp:45,atk:25,def:50,spa:25,spd:25,spe:35},curiosities:['Gera calor interno para acelerar a evolução.','O interior está em constante transformação.','Pode usar Poison Sting, ao contrário do que muitos pensam.']},
  {id:15,name:'Beedrill',types:['Bug','Poison'],desc:'Voa a alta velocidade e ataca com ferrões venenosos nas patas e abdômen.',abilities:['Swarm','Sniper'],stats:{hp:65,atk:90,def:40,spa:45,spd:80,spe:75},curiosities:['Tem Mega Evolução com velocidade absurda.','Um enxame pode derrubar uma árvore inteira.','Extremamente territorial — nunca entre em sua floresta.']},
  {id:16,name:'Pidgey',types:['Normal','Flying'],desc:'Muito gentil, prefere evitar conflitos. Levanta poeira com as asas para escapar.',abilities:['Keen Eye','Tangled Feet','Big Pecks'],stats:{hp:40,atk:45,def:40,spa:35,spd:35,spe:56},curiosities:['Primeiro Pokémon voador que muitos treinadores capturam.','Tem senso de direção perfeito, nunca se perde.','Encontra o caminho de volta para casa de qualquer lugar.']},
  {id:17,name:'Pidgeotto',types:['Normal','Flying'],desc:'Muito territorial, patrulha uma área de 100km². Carrega presas com garras poderosas.',abilities:['Keen Eye','Tangled Feet','Big Pecks'],stats:{hp:63,atk:60,def:55,spa:50,spd:50,spe:71},curiosities:['Ash teve um Pidgeot famoso no anime.','Um dos primeiros Pokémon que Ash capturou.','As garras seguram presas pesadas por longas distâncias.']},
  {id:18,name:'Pidgeot',types:['Normal','Flying'],desc:'Pode atingir velocidade de Mach 2. Caça atraindo presas com suas asas douradas.',abilities:['Keen Eye','Tangled Feet','Big Pecks'],stats:{hp:83,atk:80,def:75,spa:70,spd:70,spe:101},curiosities:['Tem Mega Evolução com velocidade ainda maior.','Pode criar tornados agitando suas asas enormes.','Símbolo de liberdade no mundo Pokémon.']},
  {id:19,name:'Rattata',types:['Normal'],desc:'Incrivelmente rápido, constrói ninhos em qualquer lugar. Dentes afiados roem quase tudo.',abilities:['Run Away','Guts','Hustle'],stats:{hp:30,atk:56,def:35,spa:25,spd:35,spe:72},curiosities:['Prolifera rapidamente: dezenas de filhotes por ano.','Os dentes nunca param de crescer.','É o Pokémon do Joey, que está no "top porcentagem".']},
  {id:20,name:'Raticate',types:['Normal'],desc:'Os dentes afiados crescem continuamente. Para desgastá-los, rói árvores e edificações.',abilities:['Run Away','Guts','Hustle'],stats:{hp:55,atk:81,def:60,spa:50,spd:70,spe:97},curiosities:['Pode nadar usando os bigodes como boia.','Os dentes cortam concreto e madeira dura.','Team Rocket usa Raticate nos jogos antigos.']},
  {id:21,name:'Spearow',types:['Normal','Flying'],desc:'Muito voraz, come insetos nos campos. Briga com Pidgey por território.',abilities:['Keen Eye','Sniper'],stats:{hp:40,atk:60,def:30,spa:31,spd:31,spe:70},curiosities:['Ataca humanos que entram em seu território.','A voz rouca alerta companheiros de perigo.','Quase matou Ash no primeiro episódio do anime.']},
  {id:22,name:'Fearow',types:['Normal','Flying'],desc:'Com asas grandes, voa por um dia inteiro sem pouso. Usa o bico longo para pegar presas.',abilities:['Keen Eye','Sniper'],stats:{hp:65,atk:90,def:65,spa:61,spd:61,spe:100},curiosities:['Mergulha a velocidades impressionantes para capturar peixes.','O bico penetra o solo para encontrar minhocas.','É um dos principais predadores Bug-type em Kanto.']},
  {id:23,name:'Ekans',types:['Poison'],desc:'Enrola-se para descansar e se proteger. Engole Pokémon inteiros.',abilities:['Intimidate','Shed Skin','Unnerve'],stats:{hp:35,atk:60,def:44,spa:40,spd:54,spe:55},curiosities:['Ekans é "Snake" ao contrário.','Usa a língua para detectar cheiros como serpentes reais.','Jessie do Team Rocket tem um Ekans que virou Arbok.']},
  {id:24,name:'Arbok',types:['Poison'],desc:'O padrão no peito varia por região. Existem mais de 20 variantes no mundo.',abilities:['Intimidate','Shed Skin','Unnerve'],stats:{hp:60,atk:85,def:69,spa:65,spd:79,spe:80},curiosities:['Arbok é "Kobra" ao contrário.','Pode engolir presas cinco vezes maior que si mesmo.','O padrão aterrorizante paralisa de medo os adversários.']},
  {id:25,name:'Pikachu',types:['Electric'],desc:'Quando vários se reúnem, geram raios poderosos que causam incêndios em florestas.',abilities:['Static','Lightning Rod'],stats:{hp:35,atk:55,def:40,spa:50,spd:50,spe:90},curiosities:['É o mascote oficial de toda a franquia Pokémon.','O Pikachu do Ash nunca evolui — por escolha própria.','Foi planejado para ter uma pré-evolução além de Pichu.']},
  {id:26,name:'Raichu',types:['Electric'],desc:'Se o volume de eletricidade for muito alto, brilha levemente no escuro.',abilities:['Static','Lightning Rod'],stats:{hp:60,atk:90,def:55,spa:90,spd:80,spe:110},curiosities:['Raichu de Alola é Elétrico/Psíquico e flutua na cauda.','A eletricidade pode causar amnésia em humanos.','Raramente evolui naturalmente — precisa da Pedra Trovão.']},
  {id:27,name:'Sandshrew',types:['Ground'],desc:'Cava buracos no solo árido. Quando ameaçado, enrola-se em bola defensiva.',abilities:['Sand Veil','Sand Rush'],stats:{hp:50,atk:75,def:85,spa:20,spd:30,spe:40},curiosities:['Enrolado pode rolar como bola.','É excepcionalmente resistente a doenças.','Versão de Alola é do tipo Gelo/Aço.']},
  {id:28,name:'Sandslash',types:['Ground'],desc:'Os espinhos ficam eretos quando ameaçado. Pode escalar arbustos de espinhos.',abilities:['Sand Veil','Sand Rush'],stats:{hp:75,atk:100,def:110,spa:45,spd:55,spe:65},curiosities:['Usa os espinhos para escalar paredes íngremes.','As garras são constantemente afiadas contra pedras.','A versão Alola usa espinhos de gelo como arma.']},
  {id:29,name:'Nidoran♀',types:['Poison'],desc:'Muito gentil normalmente, mas os chifres se enchem de veneno quando tem medo.',abilities:['Poison Point','Rivalry','Hustle'],stats:{hp:55,atk:47,def:52,spa:40,spd:40,spe:41},curiosities:['Um dos primeiros Pokémon com diferença de gênero.','Os chifres das fêmeas são menores que os dos machos.','O veneno pode se tornar paralisante conforme envelhece.']},
  {id:30,name:'Nidorina',types:['Poison'],desc:'Os dentes e garras crescem devagar. Prefere ataques usando o corpo para não machucar filhotes.',abilities:['Poison Point','Rivalry','Hustle'],stats:{hp:70,atk:62,def:67,spa:55,spd:55,spe:56},curiosities:['Nidorina e Nidoqueen não conseguem procriar.','Em grupo, cuida dos filhotes de toda a colônia.','O sistema de veneno fica mais complexo com a evolução.']},
  {id:31,name:'Nidoqueen',types:['Poison','Ground'],desc:'A pele é coberta com escamas duras como pedra. Protege os filhotes com o próprio corpo.',abilities:['Poison Point','Rivalry','Sheer Force'],stats:{hp:90,atk:92,def:87,spa:75,spd:85,spe:76},curiosities:['Uma das poucas fêmeas-only com moveset poderoso.','Sheer Force é sua melhor habilidade competitivamente.','Com Nidoking, formam um dos melhores duos de doubles.']},
  {id:32,name:'Nidoran♂',types:['Poison'],desc:'Fica em guarda com os ouvidos pontudos. O chifre venenoso na testa é sua arma principal.',abilities:['Poison Point','Rivalry','Hustle'],stats:{hp:46,atk:57,def:40,spa:40,spd:40,spe:50},curiosities:['Chifres maiores e mais venenosos que os da fêmea.','Os ouvidos localizam a origem de qualquer som.','O veneno do chifre é mais concentrado que o da fêmea.']},
  {id:33,name:'Nidorino',types:['Poison'],desc:'Um Pokémon agressivo que ataca qualquer coisa com seus chifres venenosos.',abilities:['Poison Point','Rivalry','Hustle'],stats:{hp:61,atk:72,def:57,spa:55,spd:55,spe:65},curiosities:['Muito mais agressivo que sua forma anterior.','Na batalha de abertura do GB original, luta contra Gengar.','Seus chifres são mais duros que diamante.']},
  {id:34,name:'Nidoking',types:['Poison','Ground'],desc:'Com a cauda poderosa, pode derrubar uma torre de metal. O chifre penetra qualquer coisa.',abilities:['Poison Point','Rivalry','Sheer Force'],stats:{hp:81,atk:102,def:77,spa:85,spd:75,spe:85},curiosities:['Um dos Pokémon mais versáteis competitivamente de Kanto.','A cauda é mais perigosa que os chifres.','Com Sheer Force e Life Orb, causa dano devastador.']},
  {id:35,name:'Clefairy',types:['Fairy'],desc:'Aqueles que avistam Clefairy dançando sob a lua cheia serão agraciados com boa sorte.',abilities:['Cute Charm','Magic Guard','Friend Guard'],stats:{hp:70,atk:45,def:48,spa:60,spd:65,spe:35},curiosities:['Era para ser o mascote original, antes de Pikachu.','Vive perto do Monte Moon, onde meteoritos caem.','Pode aprender quase todos os TMs, tornando-o versátil.']},
  {id:36,name:'Clefable',types:['Fairy'],desc:'Criatura rara e tímida, nunca deixa ninguém vê-la facilmente. Possui ouvidos aguçados.',abilities:['Cute Charm','Magic Guard','Unaware'],stats:{hp:95,atk:70,def:73,spa:95,spd:90,spe:60},curiosities:['Clefable com Magic Guard é excelente competitivamente.','Pode escutar uma conversa a 1km de distância.','Considerado um Pokémon mágico de boa sorte.']},
  {id:37,name:'Vulpix',types:['Fire'],desc:'Ao nascer tem uma cauda que se divide em seis conforme cresce.',abilities:['Flash Fire','Drought'],stats:{hp:38,atk:41,def:40,spa:50,spd:65,spe:65},curiosities:['Vulpix de Alola é do tipo Gelo.','Um dos Pokémon favoritos dos fãs pela aparência fofa.','Controla a temperatura interna do próprio corpo.']},
  {id:38,name:'Ninetales',types:['Fire'],desc:'Extremamente inteligente e rancoroso. Dizem que pode viver por 1000 anos.',abilities:['Flash Fire','Drought'],stats:{hp:73,atk:76,def:75,spa:81,spd:100,spe:100},curiosities:['Pode lançar maldições em quem toca suas caudas sem permissão.','Baseado no Kitsune da mitologia japonesa.','Ninetales de Alola com Drought é forte no meta de Neve.']},
  {id:39,name:'Jigglypuff',types:['Normal','Fairy'],desc:'Quando começa a cantar, não para até que os inimigos adormeçam.',abilities:['Cute Charm','Competitive','Friend Guard'],stats:{hp:115,atk:45,def:20,spa:45,spd:25,spe:20},curiosities:['Fica irritado quando adversários dormem durante seu canto.','Tem o maior HP base dos Pokémon normais de Kanto.','Desenha nos rostos de quem dorme no anime.']},
  {id:40,name:'Wigglytuff',types:['Normal','Fairy'],desc:'O pelo elástico pode se esticar infinitamente. Os olhos grandes hipnotizam os inimigos.',abilities:['Cute Charm','Competitive','Frisk'],stats:{hp:140,atk:70,def:45,spa:85,spd:50,spe:45},curiosities:['Maior HP base entre os Pokémon normais de Kanto.','No Mistério da Caverna, um Wigglytuff é o Grão-Mestre.','Pode esticar o corpo para assustar predadores.']},
  {id:41,name:'Zubat',types:['Poison','Flying'],desc:'Sem olhos, navega usando ultrassom. Habita cavernas e evita a luz do sol.',abilities:['Inner Focus','Infiltrator'],stats:{hp:40,atk:45,def:35,spa:30,spd:40,spe:55},curiosities:['O Pokémon encontrado com mais frequência em cavernas.','Apesar de cego, tem ecolocalização perfeita.','Monte Moon e Vitória Road são infestados de Zubat.']},
  {id:42,name:'Golbat',types:['Poison','Flying'],desc:'Bebe grandes quantidades de sangue de uma só vez. Às vezes fica pesado demais para voar.',abilities:['Inner Focus','Infiltrator'],stats:{hp:75,atk:80,def:70,spa:65,spd:75,spe:90},curiosities:['Pode beber até 300ml de sangue num único ataque.','Evolui para Crobat quando a amizade é alta.','Os dentes afiados perfuram até couro grosso.']},
  {id:43,name:'Oddish',types:['Grass','Poison'],desc:'De dia enterra a cabeça no solo. À noite caminha dispersando pólen venenoso.',abilities:['Chlorophyll','Run Away'],stats:{hp:45,atk:50,def:55,spa:75,spd:65,spe:30},curiosities:['Planta os próprios pés no solo para absorver nutrientes.','O pólen dispersado à noite causa sonolência.','Baseado no conceito de mandrágora da cultura popular.']},
  {id:44,name:'Gloom',types:['Grass','Poison'],desc:'O néctar escorregadio tem odor terrível. Curiosamente, alguns insetos adoram.',abilities:['Chlorophyll','Stench'],stats:{hp:60,atk:65,def:70,spa:85,spd:75,spe:40},curiosities:['O odor pode ser detectado a 1km de distância.','O líquido é paradoxalmente atraente para certos insetos.','Baseado na flor Rafflesia, a maior e mais fedorenta do mundo.']},
  {id:45,name:'Vileplume',types:['Grass','Poison'],desc:'Pétalas enormes liberam pó venenoso ao serem agitadas.',abilities:['Chlorophyll','Effect Spore'],stats:{hp:75,atk:80,def:85,spa:110,spd:90,spe:50},curiosities:['Maior Sp. Atk dos Pokémon de Grama de Kanto.','As pétalas causam paralisia, veneno ou sono.','A flor pesa tanto que dificilmente anda reto.']},
  {id:46,name:'Paras',types:['Bug','Grass'],desc:'Fungos crescem em suas costas e liberam esporos que causam sono.',abilities:['Effect Spore','Dry Skin','Damp'],stats:{hp:35,atk:70,def:55,spa:45,spd:55,spe:25},curiosities:['Os cogumelos são parasitas que controlam o Pokémon.','Ao evoluir, os fungos ficam ainda maiores e dominantes.','Baseado no fungo parasita Ophiocordyceps real.']},
  {id:47,name:'Parasect',types:['Bug','Grass'],desc:'O cogumelo parasita tomou conta de todo o corpo. A criatura original perdeu a vontade.',abilities:['Effect Spore','Dry Skin','Damp'],stats:{hp:60,atk:95,def:80,spa:60,spd:80,spe:30},curiosities:['É tecnicamente um zumbi — a criatura foi consumida pelo fungo.','Pode usar Spore para adormecer qualquer alvo.','Os olhos vazios sugerem que não há mais consciência.']},
  {id:48,name:'Venonat',types:['Bug','Poison'],desc:'Os olhos funcionam como radar no escuro. O corpo peludo repele golpes menores.',abilities:['Compound Eyes','Tinted Lens','Run Away'],stats:{hp:60,atk:55,def:50,spa:40,spd:55,spe:45},curiosities:['Curiosamente parece mais com Butterfree do que Caterpie.','Os pelos absorvem impactos de golpes fracos.','Rumores de que deveria evoluir para Butterfree eram comuns.']},
  {id:49,name:'Venomoth',types:['Bug','Poison'],desc:'As escamas das asas carregam veneno. Cor escura paralisa, clara envenena.',abilities:['Shield Dust','Tinted Lens','Wonder Skin'],stats:{hp:70,atk:65,def:60,spa:90,spd:75,spe:90},curiosities:['Escamas que mudam de efeito dependendo da cor.','Um dos melhores usuários de Quiver Dance.','Voa silenciosamente por ser coberto de escamas.']},
  {id:50,name:'Diglett',types:['Ground'],desc:'Vive debaixo da terra, cavando túneis. Seu corpo completo é um mistério.',abilities:['Sand Veil','Arena Trap','Sand Force'],stats:{hp:10,atk:55,def:25,spa:35,spd:45,spe:95},curiosities:['Ninguém jamais viu o corpo completo de Diglett.','Tem o menor HP base de todos os Pokémon de Kanto.','Arena Trap prende adversários terrestres no campo.']},
  {id:51,name:'Dugtrio',types:['Ground'],desc:'Três Diglett unidos. Vibram o chão ao se moverem rapidamente.',abilities:['Sand Veil','Arena Trap','Sand Force'],stats:{hp:35,atk:100,def:50,spa:50,spd:70,spe:120},curiosities:['Formado por três Diglett — mas se são um ou três é mistério.','Velocidade impressionante para um tipo Terra.','Arena Trap + alta velocidade tornam-no excelente caçador.']},
  {id:52,name:'Meowth',types:['Normal'],desc:'Obcecado por objetos brilhantes. Coleta moedas e objetos reluzentes à noite.',abilities:['Pickup','Technician','Unnerve'],stats:{hp:40,atk:45,def:35,spa:40,spd:40,spe:90},curiosities:['O Meowth do Team Rocket é o único Pokémon que fala idioma humano.','Aprendeu a falar para impressionar uma Meowth fêmea.','A moeda na testa brilha quando está de bom humor.']},
  {id:53,name:'Persian',types:['Normal'],desc:'O cristal na testa indica saúde. Quando brilha, está prestes a atacar.',abilities:['Limber','Technician','Unnerve'],stats:{hp:65,atk:70,def:60,spa:65,spd:65,spe:115},curiosities:['Giovanni é frequentemente visto acariciando seu Persian.','Persian de Alola é do tipo Sombrio.','Aparência elegante contrasta com temperamento traiçoeiro.']},
  {id:54,name:'Psyduck',types:['Water'],desc:'Sofre de dor de cabeça constante. Quando a dor se intensifica, usa poderes psíquicos.',abilities:['Damp','Cloud Nine','Swift Swim'],stats:{hp:50,atk:52,def:48,spa:65,spd:50,spe:55},curiosities:['Companheiro mais famoso de Misty no anime.','A dor é causada pelo esforço de conter seus poderes.','Em dor máxima, pode usar telepatia e telecinese.']},
  {id:55,name:'Golduck',types:['Water'],desc:'Nada mais rápido que qualquer nadador. O cristal na testa brilha ao usar poderes psíquicos.',abilities:['Damp','Cloud Nine','Swift Swim'],stats:{hp:80,atk:82,def:78,spa:95,spd:80,spe:85},curiosities:['Nada tão rápido que parece teleportar na água.','O cristal vermelho amplifica os poderes psíquicos.','Frequentemente confundido com a criatura japonesa Kappa.']},
  {id:56,name:'Mankey',types:['Fighting'],desc:'Extremamente raivoso sem motivo. Um grupo inteiro fica furioso se um membro se irritar.',abilities:['Vital Spirit','Anger Point','Defiant'],stats:{hp:40,atk:80,def:35,spa:35,spd:45,spe:70},curiosities:['Pode ficar com raiva por razões absolutamente triviais.','Vive em bandos nas árvores, raramente desce ao chão.','A raiva amplifica significativamente a sua força física.']},
  {id:57,name:'Primeape',types:['Fighting'],desc:'Uma vez em fúria, não para até destruir tudo. A raiva aumenta sua força.',abilities:['Vital Spirit','Anger Point','Defiant'],stats:{hp:65,atk:105,def:60,spa:60,spd:70,spe:95},curiosities:['Pode morrer de raiva se ficar bravo por muito tempo.','Ash capturou um Primeape e o deixou para ser lutador.','Tem evolução Annihilape, introduzida em Paldea.']},
  {id:58,name:'Growlithe',types:['Fire'],desc:'Extremamente leal, late para afastar intrusos. Não abandona sua posição até ser ordenado.',abilities:['Intimidate','Flash Fire','Justified'],stats:{hp:55,atk:70,def:45,spa:70,spd:50,spe:60},curiosities:['Considerado o Pokémon mais leal que existe.','A polícia de Kanto usa Growlithe para trabalho de faro.','Precisa de uma Pedra Fogo para evoluir.']},
  {id:59,name:'Arcanine',types:['Fire'],desc:'Considerado majestoso pelo mundo todo. Corre 10.000km em um único dia sem descanso.',abilities:['Intimidate','Flash Fire','Justified'],stats:{hp:90,atk:110,def:80,spa:100,spd:80,spe:95},curiosities:['Era originalmente planejado como Pokémon Lendário.','Isso explica a categoria "Pokémon Lendário" no Pokédex.','Baseado no cão do fogo da mitologia chinesa.']},
  {id:60,name:'Poliwag',types:['Water'],desc:'A espiral no abdômen são os intestinos visíveis pela pele transparente.',abilities:['Water Absorb','Damp','Swift Swim'],stats:{hp:40,atk:50,def:40,spa:40,spd:40,spe:90},curiosities:['A espiral é um intestino real visível pela pele fina.','As pernas são frágeis demais para caminhar — prefere nadar.','Pode evoluir em Poliwrath ou Politoed dependendo do item.']},
  {id:61,name:'Poliwhirl',types:['Water'],desc:'Os grandes olhos hipnotizam os inimigos. A espiral em rotação causa sono.',abilities:['Water Absorb','Damp','Swift Swim'],stats:{hp:65,atk:65,def:65,spa:50,spd:50,spe:90},curiosities:['Pode viver tanto na terra quanto na água.','A espiral giratória tem efeito hipnótico real.','Ken Sugimori, criador de Pokémon, tem tatuagem de Poliwag.']},
  {id:62,name:'Poliwrath',types:['Water','Fighting'],desc:'Músculos poderosos permitem nadar distâncias oceânicas. Supera humanos olímpicos.',abilities:['Water Absorb','Damp','Swift Swim'],stats:{hp:90,atk:95,def:95,spa:70,spd:90,spe:70},curiosities:['Pode nadar o Pacífico sem parar.','Tem alto Sp. Def entre os lutadores de Kanto.','Alternativa ao Poliwrath é o Politoed de Johto.']},
  {id:63,name:'Abra',types:['Psychic'],desc:'Dorme 18 horas por dia para acumular energia psíquica. Consegue teleportar durante o sono.',abilities:['Synchronize','Inner Focus','Magic Guard'],stats:{hp:25,atk:20,def:15,spa:105,spd:55,spe:90},curiosities:['Um dos mais difíceis de capturar: sempre usa Teleport.','Dorme quase todo o dia para manter os poderes.','Com 105 de Sp. Atk base, é surpreendentemente poderoso.']},
  {id:64,name:'Kadabra',types:['Psychic'],desc:'Emite ondas alfa ao usar seus poderes. Aparece perto de quem tem poderes latentes.',abilities:['Synchronize','Inner Focus','Magic Guard'],stats:{hp:40,atk:35,def:30,spa:120,spd:70,spe:105},curiosities:['Foi motivo de processo judicial por Uri Geller por anos.','A colher amplifica seus poderes psíquicos.','Precisa ser trocado para evoluir.']},
  {id:65,name:'Alakazam',types:['Psychic'],desc:'QI de 5000. Memoriza tudo desde o nascimento. Os bigodes ampliam poderes psíquicos.',abilities:['Synchronize','Inner Focus','Magic Guard'],stats:{hp:55,atk:50,def:45,spa:135,spd:95,spe:120},curiosities:['Tem o maior QI de todos os Pokémon — estimado em 5000.','O cérebro cresce continuamente; o corpo enfraquece.','Mega Alakazam tem 175 de Sp. Atk.']},
  {id:66,name:'Machop',types:['Fighting'],desc:'Adora lutar. Passa os dias praticando vários golpes para ficar mais forte.',abilities:['Guts','No Guard','Steadfast'],stats:{hp:70,atk:80,def:50,spa:35,spd:35,spe:35},curiosities:['Tem seis tentáculos usados para diferentes técnicas.','Pode carregar um Graveler em cada braço com facilidade.','Baseado em lutadores de wrestling.']},
  {id:67,name:'Machoke',types:['Fighting'],desc:'Usa um cinto de poder para reduzir a própria força, evitando machucar aliados.',abilities:['Guts','No Guard','Steadfast'],stats:{hp:80,atk:100,def:70,spa:50,spd:60,spe:45},curiosities:['O cinto controla sua força absurda.','Um dos poucos Pokémon mostrados fazendo trabalho físico.','Precisa ser trocado para evoluir para Machamp.']},
  {id:68,name:'Machamp',types:['Fighting'],desc:'Com quatro braços, pode disparar 1000 socos por segundo. Move montanhas com um empurrão.',abilities:['Guts','No Guard','Steadfast'],stats:{hp:90,atk:130,def:80,spa:65,spd:85,spe:55},curiosities:['No Guard + Dynamic Punch garante confusão sempre.','Um dos mais poderosos fisicamente de toda 1ª geração.','Frequentemente usado em competições de força.']},
  {id:69,name:'Bellsprout',types:['Grass','Poison'],desc:'Prefere solos úmidos. O corpo flexível agarra presas com as folhas.',abilities:['Chlorophyll','Gluttony'],stats:{hp:50,atk:75,def:35,spa:70,spd:30,spe:40},curiosities:['Pode viver apenas da água do solo.','As raízes absorvem nutrientes rapidamente.','Baseado em plantas carnívoras como a Venus Fly Trap.']},
  {id:70,name:'Weepinbell',types:['Grass','Poison'],desc:'Possui ácido que dissolve tudo que ingere. Dorme pendurado em galhos.',abilities:['Chlorophyll','Gluttony'],stats:{hp:65,atk:90,def:50,spa:85,spd:45,spe:55},curiosities:['O ácido dissolve insetos em segundos.','Dorme suspenso pelos galhos para não cair.','Ao ser molestado, solta-se e escapa rapidamente.']},
  {id:71,name:'Victreebel',types:['Grass','Poison'],desc:'Atrai presas com aroma doce, depois as engole no líquido ácido.',abilities:['Chlorophyll','Gluttony'],stats:{hp:80,atk:105,def:65,spa:100,spd:60,spe:70},curiosities:['James do Team Rocket tem um Victreebel que tenta comê-lo.','Baseado na planta carnívora Nepenthes.','O aroma pode atrair humanos desavisados.']},
  {id:72,name:'Tentacool',types:['Water','Poison'],desc:'O corpo é 99% água. Concentra a luz do sol para criar raios de energia.',abilities:['Clear Body','Liquid Ooze','Rain Dish'],stats:{hp:40,atk:40,def:35,spa:50,spd:100,spe:70},curiosities:['O Pokémon mais abundante dos oceanos de Kanto.','O corpo quase transparente dificulta sua localização.','Pode paralisar humanos com os tentáculos.']},
  {id:73,name:'Tentacruel',types:['Water','Poison'],desc:'Os 80 tentáculos podem ser retraídos. Quando estendidos, criam armadilha impenetrável.',abilities:['Clear Body','Liquid Ooze','Rain Dish'],stats:{hp:80,atk:70,def:65,spa:80,spd:120,spe:100},curiosities:['Maior Sp. Def dos Pokémon de Água de Kanto.','Pode envenenar múltiplos alvos simultaneamente.','Bancos de Tentacruel destroem barcos de pesca no anime.']},
  {id:74,name:'Geodude',types:['Rock','Ground'],desc:'Comum em campos e montanhas. Fica tão parado que é difícil distingui-lo de pedras.',abilities:['Rock Head','Sturdy','Sand Veil'],stats:{hp:40,atk:80,def:100,spa:30,spd:30,spe:20},curiosities:['Tão parado que caminhantes pisam neles sem querer.','Forma regional de Alola: Elétrico/Pedra.','Explosion é seu golpe mais famoso.']},
  {id:75,name:'Graveler',types:['Rock','Ground'],desc:'Rola por encostas e esmaga tudo no caminho. Não liga para obstáculos.',abilities:['Rock Head','Sturdy','Sand Veil'],stats:{hp:55,atk:95,def:115,spa:45,spd:45,spe:35},curiosities:['Come rochas e pedras como alimento.','Ao rolar perde fragmentos que viram novos Geodude.','Evolui via troca para Golem.']},
  {id:76,name:'Golem',types:['Rock','Ground'],desc:'Uma vez por ano troca a carapaça. A nova pele endurece rapidamente ao ar.',abilities:['Rock Head','Sturdy','Sand Veil'],stats:{hp:80,atk:120,def:130,spa:55,spd:65,spe:45},curiosities:['Pode rolar por montanhas inteiras sem se machucar.','A carapaça anual é considerada boa sorte.','Golem de Alola é do tipo Pedra/Elétrico.']},
  {id:77,name:'Ponyta',types:['Fire'],desc:'As patas pisam em brasas sem sentir nada. Recém-nascidos têm chamas fracas que crescem.',abilities:['Run Away','Flash Fire','Flame Body'],stats:{hp:50,atk:85,def:55,spa:65,spd:65,spe:90},curiosities:['As chamas ficam mais fortes conforme ganha confiança.','Pode pular obstáculos enormes com facilidade.','Ponyta de Galar é do tipo Psíquico com juba arco-íris.']},
  {id:78,name:'Rapidash',types:['Fire'],desc:'Pode atingir 240km/h. Corre até o pôr do sol, desafiando todos os rivais.',abilities:['Run Away','Flash Fire','Flame Body'],stats:{hp:65,atk:100,def:70,spa:80,spd:80,spe:105},curiosities:['Um dos Pokémon mais rápidos de Kanto.','A juba em chamas não queima o cavaleiro domesticado.','Adora disputar corridas com qualquer coisa que se mova.']},
  {id:79,name:'Slowpoke',types:['Water','Psychic'],desc:'Leva 5 segundos para sentir dor. Pesca com a cauda esperando por horas.',abilities:['Oblivious','Own Tempo','Regenerator'],stats:{hp:90,atk:65,def:65,spa:40,spd:40,spe:15},curiosities:['Tem a menor velocidade entre os Pokémon de Kanto.','A cauda tem sabor adocicado e é iguaria em algumas regiões.','Regenerator torna-o excelente como pivot competitivo.']},
  {id:80,name:'Slowbro',types:['Water','Psychic'],desc:'O Shellder no rabo injeta toxinas que estimulam o cérebro, tornando-o mais inteligente.',abilities:['Oblivious','Own Tempo','Regenerator'],stats:{hp:95,atk:75,def:110,spa:100,spd:80,spe:30},curiosities:['Se o Shellder cair, Slowbro volta a ser Slowpoke.','Não pode virar Slowking se o Shellder estiver na cauda.','É um dos melhores muros de Water/Psychic de Kanto.']},
  {id:81,name:'Magnemite',types:['Electric','Steel'],desc:'Flutua usando ondas eletromagnéticas. Se aproxima de aparelhos elétricos para se alimentar.',abilities:['Magnet Pull','Sturdy','Analytic'],stats:{hp:25,atk:35,def:70,spa:95,spd:55,spe:45},curiosities:['Um dos primeiros tipos Aço introduzidos retroativamente.','Magnet Pull aprisiona Pokémon de Aço.','Parafusos e ímãs fazem parte de sua estrutura corporal.']},
  {id:82,name:'Magneton',types:['Electric','Steel'],desc:'Três Magnemite unidos por força magnética. A força eletromagnética é três vezes maior.',abilities:['Magnet Pull','Sturdy','Analytic'],stats:{hp:50,atk:60,def:95,spa:120,spd:70,spe:70},curiosities:['Formado por exatamente 3 Magnemite — sempre.','A temperatura sobe 3,5°C num raio de 100m ao aparecer.','Evolui para Magnezone com Thunder Stone.']},
  {id:83,name:"Farfetch'd",types:['Normal','Flying'],desc:'Nunca se separa do talo que carrega. Usado para lutar e construir ninhos.',abilities:['Keen Eye','Inner Focus','Defiant'],stats:{hp:52,atk:90,def:55,spa:58,spd:62,spe:60},curiosities:["Tão raro que está em perigo de extinção.",'O talo é tão valioso que luta até a morte para protegê-lo.',"Galarian Farfetch'd evolui para Sirfetch'd."]},
  {id:84,name:'Doduo',types:['Normal','Flying'],desc:'Apesar de ter asas, não pode voar. Compensa com velocidade excepcional na corrida.',abilities:['Run Away','Early Bird','Tangled Feet'],stats:{hp:35,atk:85,def:45,spa:35,spd:35,spe:75},curiosities:['Duas cabeças que pensam independentemente mas raramente discordam.','Pode correr 100km/h mesmo com corpo pesado.','Teoricamente regrediu evolutivamente e perdeu o voo.']},
  {id:85,name:'Dodrio',types:['Normal','Flying'],desc:'As três cabeças representam raiva, alegria e tristeza. Raramente dormem todas ao mesmo tempo.',abilities:['Run Away','Early Bird','Tangled Feet'],stats:{hp:60,atk:110,def:70,spa:60,spd:60,spe:110},curiosities:['Nunca dorme completamente: sempre ao menos uma cabeça acorda.','Um dos Pokémon mais rápidos do tipo Normal.','As três cabeças têm personalidades completamente diferentes.']},
  {id:86,name:'Seel',types:['Water'],desc:'Ama ambientes gelados. Quanto mais frio, mais energético. O chifre quebra gelo.',abilities:['Thick Fat','Hydration','Ice Body'],stats:{hp:65,atk:45,def:55,spa:45,spd:70,spe:45},curiosities:['Usa o chifre para abrir buracos no gelo e respirar.','Extremamente ativo abaixo de 0°C.','A pele espessa protege do frio extremo.']},
  {id:87,name:'Dewgong',types:['Water','Ice'],desc:'Nada graciosamente sob o gelo. Armazena energia do sol para nadar à noite.',abilities:['Thick Fat','Hydration','Ice Body'],stats:{hp:90,atk:70,def:80,spa:70,spd:95,spe:70},curiosities:['Inspirado nas sereias e dugongos reais.','Pode nadar a 8 nós em águas geladas.','Thick Fat reduz dano de Fogo e Gelo pela metade.']},
  {id:88,name:'Grimer',types:['Poison'],desc:'Formado de lodo tóxico que ganhou vida. Onde passa, a terra fica estéril por três anos.',abilities:['Stench','Sticky Hold','Poison Touch'],stats:{hp:80,atk:80,def:50,spa:40,spd:50,spe:25},curiosities:['Formado por lixo e poluição industrial.','Bactérias únicas podem degradar resíduos tóxicos.','Versão de Alola é Veneno/Sombrio e come lixo eletrônico.']},
  {id:89,name:'Muk',types:['Poison'],desc:'O corpo em expansão absorve tudo que toca. O odor pode causar perda de consciência.',abilities:['Stench','Sticky Hold','Poison Touch'],stats:{hp:105,atk:105,def:75,spa:65,spd:100,spe:50},curiosities:['O simples toque faz outros Pokémon definharem.','Tem HP e Ataque impressionantes para um tipo Veneno.','Versão de Alola com tipo Veneno/Sombrio é muito amada.']},
  {id:90,name:'Shellder',types:['Water'],desc:'A concha é mais dura que qualquer metal. Fecha a concha 100x por segundo quando ameaçado.',abilities:['Shell Armor','Skill Link','Overcoat'],stats:{hp:30,atk:65,def:100,spa:45,spd:25,spe:40},curiosities:['Maior Defesa base entre Pokémon de Água de Kanto.','Skill Link + Icicle Spear é uma combinação poderosa.','O Shellder que morde a cauda de Slowpoke cria Slowbro.']},
  {id:91,name:'Cloyster',types:['Water','Ice'],desc:'Uma vez fechado, ninguém pode abri-lo de fora. Dispara espinhos como balas.',abilities:['Shell Armor','Skill Link','Overcoat'],stats:{hp:50,atk:95,def:180,spa:85,spd:45,spe:70},curiosities:['Maior Defesa física de todos os Pokémon de Kanto.','Shell Smash + Skill Link é uma das estratégias mais temidas.','O interior nunca foi visto por ninguém.']},
  {id:92,name:'Gastly',types:['Ghost','Poison'],desc:'Formado principalmente por gás. Pode envolver elefantes com sua névoa até desmaiarem.',abilities:['Levitate'],stats:{hp:30,atk:35,def:30,spa:100,spd:35,spe:80},curiosities:['Um dos poucos tipos Fantasma da 1ª geração.','Pode ser dispersado pelo vento — tem medo de correntes de ar.','Com 100 de Sp. Atk base, é surpreendentemente ofensivo.']},
  {id:93,name:'Haunter',types:['Ghost','Poison'],desc:'Esconde-se na escuridão à espera de presas. Tocar em Haunter pode causar tremores.',abilities:['Levitate'],stats:{hp:45,atk:50,def:45,spa:115,spd:55,spe:95},curiosities:['Pode travar vítimas com paralisia ao toque.','Ash teve um Haunter no anime que ficou com Sabrina.','Levitate o imuniza completamente a golpes de Terra.']},
  {id:94,name:'Gengar',types:['Ghost','Poison'],desc:'Esconde-se nas sombras. A temperatura cai 10°C quando está por perto.',abilities:['Cursed Body','Levitate'],stats:{hp:60,atk:65,def:60,spa:130,spd:75,spe:110},curiosities:['Um dos Pokémon favoritos de incontáveis fãs.','Tem Mega Evolução com 170 de Sp. Atk.','Shadow Ball + Mega Gengar é uma das combinações mais letais.']},
  {id:95,name:'Onix',types:['Rock','Ground'],desc:'Escava a 80km/h. O cerne é uma bola de pedra magnética que serve de bússola.',abilities:['Rock Head','Sturdy','Weak Armor'],stats:{hp:35,atk:45,def:160,spa:30,spd:45,spe:70},curiosities:['Tem a maior Defesa base de Kanto.','Brock no anime tem um Onix icônico.','Evolui para Steelix com Metal Coat na troca.']},
  {id:96,name:'Drowzee',types:['Psychic'],desc:'Come sonhos de pessoas adormecidas. Prefere os sonhos de crianças, mais doces e coloridos.',abilities:['Insomnia','Forewarn','Inner Focus'],stats:{hp:60,atk:48,def:45,spa:43,spd:90,spe:42},curiosities:['Primeiro Pokémon a aprender Hypnosis no Pokédex.','Baseado no Tapir malaio, que devora pesadelos no folclore.','Pode prever sonhos futuros de pessoas próximas.']},
  {id:97,name:'Hypno',types:['Psychic'],desc:'Hipnotiza adversários com seu pêndulo. Há relatos de Hypno levando crianças hipnotizadas.',abilities:['Insomnia','Forewarn','Inner Focus'],stats:{hp:85,atk:73,def:70,spa:73,spd:115,spe:67},curiosities:['Baseado no hipnotista clássico com pêndulo dourado.','Maior Sp. Def dos tipos Psíquico de Kanto.','O Pokédex registra casos perturbadores de crianças hipnotizadas.']},
  {id:98,name:'Krabby',types:['Water'],desc:'A pinça maior serve para equilíbrio quando a menor é perdida. Vive em buracos na praia.',abilities:['Hyper Cutter','Shell Armor','Sheer Force'],stats:{hp:30,atk:105,def:90,spa:25,spd:25,spe:50},curiosities:['105 de Ataque base — impressionante para um estágio inicial.','Ash capturou um Krabby que virou Kingler nas Ligas.','Regenera pinças perdidas dentro de um dia.']},
  {id:99,name:'Kingler',types:['Water'],desc:'A pinça esquerda é tão pesada que é difícil de erguer — mas o golpe é devastador.',abilities:['Hyper Cutter','Shell Armor','Sheer Force'],stats:{hp:55,atk:130,def:115,spa:50,spd:50,spe:75},curiosities:['130 de Ataque — um dos mais altos de toda 1ª geração.','Sheer Force + Crabhammer é devastador.','O Kingler de Ash venceu múltiplos combates nas Ligas.']},
  {id:100,name:'Voltorb',types:['Electric'],desc:'Parece uma Poké Bola. Explode com a menor provocação. Ninguém conhece sua origem.',abilities:['Soundproof','Static','Aftermath'],stats:{hp:40,atk:30,def:50,spa:55,spd:55,spe:100},curiosities:['100 de velocidade base — rapidíssimo para um Pokémon elétrico.','Ninguém sabe se evoluiu de uma Poké Bola ou é coincidência.','Self-Destruct e Explosion são seus golpes mais temidos.']},
  {id:101,name:'Electrode',types:['Electric'],desc:'O Pokémon que mais facilmente explode. Quanto mais energia absorve, mais instável fica.',abilities:['Soundproof','Static','Aftermath'],stats:{hp:60,atk:50,def:70,spa:80,spd:80,spe:140},curiosities:['140 de velocidade — um dos mais rápidos de toda 1ª geração.','Pode usar Explosion para encerrar batalhas desesperadas.','Usado em usinas de energia como armazenamento — perigosamente.']},
  {id:102,name:'Exeggcute',types:['Grass','Psychic'],desc:'Os seis ovos se comunicam telepaticamente. Ovos rachados se recuperam ao se juntarem.',abilities:['Chlorophyll','Harvest'],stats:{hp:60,atk:40,def:80,spa:60,spd:45,spe:40},curiosities:['Na verdade são sementes, não ovos.','Os seis agem como um organismo único por telepatia.','Harvest permite usar Berries indefinidamente.']},
  {id:103,name:'Exeggutor',types:['Grass','Psychic'],desc:'Cada cabeça tem mente própria e às vezes discordam entre si.',abilities:['Chlorophyll','Harvest'],stats:{hp:95,atk:95,def:85,spa:125,spd:65,spe:55},curiosities:['Exeggutor de Alola é Grama/Dragão com 10.9m de altura.','As cabeças que caem do pescoço se tornam Exeggcute.','Tem 125 de Sp. Atk — extremamente poderoso.']},
  {id:104,name:'Cubone',types:['Ground'],desc:'Usa o crânio de sua mãe morta como capacete. Chora à noite, lembrando dela.',abilities:['Rock Head','Lightning Rod','Battle Armor'],stats:{hp:50,atk:50,def:95,spa:40,spd:50,spe:35},curiosities:['Considerado o Pokémon mais triste do Pokédex.','Ninguém jamais viu o rosto de Cubone sem o capacete.','Marowak Ghost na Torre Pokémon é a mãe morta de Cubone.']},
  {id:105,name:'Marowak',types:['Ground'],desc:'Supera o trauma e se torna feroz. O osso bumerangue sempre retorna após ser arremessado.',abilities:['Rock Head','Lightning Rod','Battle Armor'],stats:{hp:60,atk:80,def:110,spa:50,spd:80,spe:45},curiosities:['Marowak de Alola é Fogo/Fantasma com osso em chamas.','O osso bumerangue sempre retorna, não importa a distância.','Superar o luto transformou Cubone em algo mais forte.']},
  {id:106,name:'Hitmonlee',types:['Fighting'],desc:'As pernas se estendem ao dobro do comprimento ao chutar. Cada golpe calculado com precisão.',abilities:['Limber','Reckless','Unburden'],stats:{hp:50,atk:120,def:53,spa:35,spd:110,spe:87},curiosities:['Baseado no Bruce Lee.','Reckless aumenta dano de golpes com recuo.','Unburden dobra a velocidade ao consumir um item.']},
  {id:107,name:'Hitmonchan',types:['Fighting'],desc:'Soca mais rápido que se pode ver. Cada golpe carrega o poder de cinco socos combinados.',abilities:['Keen Eye','Iron Fist','Inner Focus'],stats:{hp:50,atk:105,def:79,spa:35,spd:110,spe:76},curiosities:['Baseado em Jackie Chan.','Iron Fist aumenta golpes de soco em 20%.','Pode dar socos até 10 vezes por segundo.']},
  {id:108,name:'Lickitung',types:['Normal'],desc:'A língua de 2m retorna ao lugar em espiral. O líquido amolece qualquer coisa que toca.',abilities:['Own Tempo','Oblivious','Cloud Nine'],stats:{hp:90,atk:55,def:75,spa:60,spd:75,spe:30},curiosities:['A língua é duas vezes mais longa que o corpo.','Se engolir algo por acidente, a língua o traz de volta.','Pode lamber qualquer coisa para analisar quimicamente.']},
  {id:109,name:'Koffing',types:['Poison'],desc:'O gás que libera é explosivo e venenoso. Não tem noção do quanto é nocivo.',abilities:['Levitate','Neutralizing Gas','Stench'],stats:{hp:40,atk:65,def:95,spa:60,spd:45,spe:35},curiosities:['James do Team Rocket tem um Koffing famoso.','O gás faz crianças doentes em áreas urbanas.','Levitate o protege de golpes do tipo Terra.']},
  {id:110,name:'Weezing',types:['Poison'],desc:'Duas cabeças de gás tóxico unidas. O gás mata plantas ao redor enquanto dorme.',abilities:['Levitate','Neutralizing Gas','Stench'],stats:{hp:65,atk:90,def:120,spa:85,spd:70,spe:60},curiosities:['Weezing de Galar é Veneno/Fada com chaminés estilizadas.','Tem defesa impressionante para um tipo Veneno.','O vapor noturno destrói toda a vegetação próxima.']},
  {id:111,name:'Rhyhorn',types:['Ground','Rock'],desc:'Constituição física mais forte que um tanque. Tem cérebro pequeníssimo e esquece batalhas.',abilities:['Lightning Rod','Rock Head','Reckless'],stats:{hp:80,atk:85,def:95,spa:30,spd:30,spe:25},curiosities:['Pode esmagar 1 tonelada sem se machucar.','Literalmente esquece batalhas logo após.','A mãe de Serena em Kalos treina Rhyhorn em corridas.']},
  {id:112,name:'Rhydon',types:['Ground','Rock'],desc:'Pode carregar 30 toneladas com o chifre. O cérebro desenvolveu ao evoluir.',abilities:['Lightning Rod','Rock Head','Reckless'],stats:{hp:105,atk:130,def:120,spa:45,spd:45,spe:40},curiosities:['Rhydon foi o primeiro Pokémon criado pela equipe de design.','Por isso ocupa o slot #001 nos dados internos do jogo.','Tem 130 de Ataque e 120 de Defesa — um tanque real.']},
  {id:113,name:'Chansey',types:['Normal'],desc:'O ovo que carrega é delicioso e nutritivo. Partilha com Pokémon feridos e humanos.',abilities:['Natural Cure','Serene Grace','Healer'],stats:{hp:250,atk:5,def:5,spa:35,spd:105,spe:50},curiosities:['250 de HP — o maior de todos os Pokémon de Kanto.','Blissey, sua evolução, tem o maior HP de todo o jogo.','Trabalha como enfermeira no Centro Pokémon.']},
  {id:114,name:'Tangela',types:['Grass'],desc:'O corpo é completamente oculto por trepadeiras azuis. Ninguém sabe o que há sob as vinhas.',abilities:['Chlorophyll','Leaf Guard','Regenerator'],stats:{hp:65,atk:55,def:115,spa:100,spd:40,spe:60},curiosities:['Ninguém sabe a aparência real de Tangela.','Regenerator é sua melhor habilidade competitivamente.','As vinhas regeneram rapidamente quando quebradas.']},
  {id:115,name:'Kangaskhan',types:['Normal'],desc:'Nasce com um bebê no marsúpio. Luta furiosamente para protegê-lo.',abilities:['Early Bird','Scrappy','Inner Focus'],stats:{hp:105,atk:95,def:80,spa:40,spd:80,spe:90},curiosities:['Mega Evolução onde o filhote sai do marsúpio e luta junto.','Um dos únicos Pokémon sempre com filhote.','Scrappy permite golpear Fantasmas com golpes Normais.']},
  {id:116,name:'Horsea',types:['Water'],desc:'Quando ameaçado, expele tinta preta como cortina de fumaça para escapar.',abilities:['Swift Swim','Sniper','Damp'],stats:{hp:30,atk:40,def:70,spa:70,spd:25,spe:60},curiosities:['Baseado no cavalo-marinho real.','Os machos de cavalos-marinhos carregam os filhotes.','Evolui para Seadra, que evolui para Kingdra com Dragon Scale.']},
  {id:117,name:'Seadra',types:['Water'],desc:'As nadadeiras foram substituídas por espinhos venenosos. O redemoinho afunda barcos.',abilities:['Poison Point','Sniper','Damp'],stats:{hp:55,atk:65,def:95,spa:95,spd:45,spe:85},curiosities:['Pode criar redemoinhos que afundam lanchas.','O veneno dos espinhos imobiliza nadadores.','Evolui para Kingdra com Dragon Scale via troca.']},
  {id:118,name:'Goldeen',types:['Water'],desc:'O chifre na testa brilhante é sua marca. Nada graciosamente como uma bailarina aquática.',abilities:['Swift Swim','Water Veil','Lightning Rod'],stats:{hp:45,atk:67,def:60,spa:35,spd:50,spe:63},curiosities:['Considerado o Pokémon mais bonito dos rios e lagos.','O chifre pode quebrar redes de pesca com facilidade.','Misty tem uma Goldeen que só usa Splash em terra.']},
  {id:119,name:'Seaking',types:['Water'],desc:'O chifre perfura pedras para criar ninhos. O macho cuida dos ovos por 40 dias sozinho.',abilities:['Swift Swim','Water Veil','Lightning Rod'],stats:{hp:80,atk:92,def:65,spa:65,spd:80,spe:68},curiosities:['Um dos poucos Pokémon com comportamento paternal.','Lightning Rod atrai e absorve ataques elétricos.','A nadadeira dorsal navega em correntezas fortes.']},
  {id:120,name:'Staryu',types:['Water'],desc:'O núcleo vermelho brilha à meia-noite. Comunica-se com estrelas pela piscagem do núcleo.',abilities:['Illuminate','Natural Cure','Analytic'],stats:{hp:30,atk:45,def:55,spa:70,spd:55,spe:85},curiosities:['Pode regenerar qualquer parte do corpo exceto o núcleo.','Natural Cure cura status ao ser retirado da batalha.','Misty tem um Staryu icônico no anime.']},
  {id:121,name:'Starmie',types:['Water','Psychic'],desc:'O núcleo irradia sete cores. Os raios coloridos possivelmente se comunicam com extraterrestres.',abilities:['Illuminate','Natural Cure','Analytic'],stats:{hp:60,atk:75,def:85,spa:100,spd:85,spe:115},curiosities:['Um dos melhores sweepers de velocidade de Kanto.','Com 115 de velocidade e 100 de Sp. Atk, é devastador.','O núcleo de 7 cores pisca em diferentes padrões.']},
  {id:122,name:'Mr. Mime',types:['Psychic','Fairy'],desc:'Cria mímicas tão convincentes que as paredes invisíveis se tornam reais ao serem tocadas.',abilities:['Soundproof','Filter','Technician'],stats:{hp:40,atk:45,def:65,spa:100,spd:120,spe:90},curiosities:['Pode criar barreiras psíquicas sólidas com as mãos.','A mãe de Ash tem um Mr. Mime que ajuda nos afazeres.','Filter reduz dano de golpes super-efetivos em 25%.']},
  {id:123,name:'Scyther',types:['Bug','Flying'],desc:'As foices são mais afiadas que qualquer faca. Corta bambu grosso em uma única passagem.',abilities:['Swarm','Technician','Steadfast'],stats:{hp:70,atk:110,def:80,spa:55,spd:80,spe:105},curiosities:['Technician + Quick Attack pode surpreender oponentes.','Evolui para Scizor com Metal Coat via troca.','Um dos Pokémon mais amados pelos fãs da 1ª geração.']},
  {id:124,name:'Jynx',types:['Ice','Psychic'],desc:'Dança hipnoticamente, fazendo inimigos dançarem junto involuntariamente.',abilities:['Oblivious','Forewarn','Dry Skin'],stats:{hp:65,atk:50,def:35,spa:115,spd:95,spe:95},curiosities:['Gerou controvérsias e a aparência foi alterada em 2002.','Com 115 de Sp. Atk, é poderoso tipo Gelo.','Dry Skin cura HP na chuva mas perde sob sol forte.']},
  {id:125,name:'Electabuzz',types:['Electric'],desc:'Vive perto de usinas, absorvendo eletricidade. Provoca apagões ao entrar nas redes.',abilities:['Static','Vital Spirit'],stats:{hp:65,atk:83,def:57,spa:95,spd:85,spe:105},curiosities:['Provoca tempestades elétricas com sua presença.','Pokémon favorito de muitos treinadores.','Evolui para Electivire com Electirizer via troca.']},
  {id:126,name:'Magmar',types:['Fire'],desc:'Vive em vulcões ativos. O calor corporal chega a 1200°C.',abilities:['Flame Body','Vital Spirit'],stats:{hp:65,atk:95,def:57,spa:100,spd:85,spe:93},curiosities:['Flame Body pode queimar o atacante no contato.','Evolui para Magmortar com Magmarizer via troca.','O bico que parece chama é na verdade orgânico.']},
  {id:127,name:'Pinsir',types:['Bug'],desc:'As garras no topo da cabeça podem quebrar qualquer coisa. Mata presas por esmagamento.',abilities:['Hyper Cutter','Mold Breaker','Moxie'],stats:{hp:65,atk:125,def:100,spa:55,spd:70,spe:85},curiosities:['125 de Ataque — um dos mais poderosos Bug de Kanto.','Tem Mega Evolução que adiciona o tipo Voador.','Moxie aumenta Ataque a cada K.O.']},
  {id:128,name:'Tauros',types:['Normal'],desc:'Uma vez em corrida de ataque, não para. Açoita com as três caudas para aumentar a fúria.',abilities:['Intimidate','Anger Point','Sheer Force'],stats:{hp:75,atk:100,def:95,spa:40,spd:70,spe:110},curiosities:['Ash capturou 30 Tauros no Safari Zone — todos de uma vez.','Um dos mais poderosos em batalha competitiva Gen 1.','Anger Point maximiza Ataque ao sofrer um crítico.']},
  {id:129,name:'Magikarp',types:['Water'],desc:'Considerado o Pokémon mais fraco. A única coisa que sabe é pular. Vive em qualquer água.',abilities:['Swift Swim','Rattled'],stats:{hp:20,atk:10,def:55,spa:15,spd:20,spe:80},curiosities:['O meme definitivo de Pokémon: inútil até evoluir.','Ao atingir nível 20, evolui para o lendário Gyarados.','Na 1ª geração, o único golpe que aprende é Splash — que não faz nada.']},
  {id:130,name:'Gyarados',types:['Water','Flying'],desc:'Uma vez em fúria, não para por meses. Seus rugidos ressoam por 100km.',abilities:['Intimidate','Moxie'],stats:{hp:95,atk:125,def:79,spa:60,spd:100,spe:81},curiosities:['Prova de que perseverança compensa: Magikarp vira monstro.','Moxie + Dragon Dance = sweep devastador.','Gyarados vermelho Shiny tem probabilidade de 1 em 8192.']},
  {id:131,name:'Lapras',types:['Water','Ice'],desc:'Gentil e bondoso, oferece transporte aos humanos. Entende a linguagem humana.',abilities:['Water Absorb','Shell Armor','Hydration'],stats:{hp:130,atk:85,def:80,spa:85,spd:95,spe:60},curiosities:['130 de HP — impressionante para um não-lendário.','Baseado no mito da criatura do Lago Ness.','Ash usou Lapras para viajar pelas Ilhas Laranja.']},
  {id:132,name:'Ditto',types:['Normal'],desc:'Pode se transformar em qualquer Pokémon que veja. A transformação é perfeita até o nível celular.',abilities:['Limber','Imposter'],stats:{hp:48,atk:48,def:48,spa:48,spd:48,spe:48},curiosities:['Imposter copia automaticamente o oponente ao entrar em campo.','Essencial para reprodução Pokémon: aceita qualquer parceiro.','Todas as estatísticas são 48 — completamente equilibrado.']},
  {id:133,name:'Eevee',types:['Normal'],desc:'Estrutura genética instável lhe dá a capacidade única de evoluir em múltiplas formas.',abilities:['Run Away','Adaptability','Anticipation'],stats:{hp:55,atk:55,def:50,spa:45,spd:65,spe:55},curiosities:['Tem 8 evoluções diferentes — a mais de qualquer Pokémon.','A forma de evolução depende da pedra, amizade ou local.','É o parceiro do protagonista em Pokémon: Lets Go Eevee.']},
  {id:134,name:'Vaporeon',types:['Water'],desc:'Pode se tornar invisível dissolvendo-se na água. Estrutura celular similar à da água.',abilities:['Water Absorb','Hydration'],stats:{hp:130,atk:65,def:60,spa:110,spd:95,spe:65},curiosities:['Water Absorb restaura HP ao ser atingido por golpes de água.','Com 130 de HP e 110 de Sp. Atk, é o Eevee mais durável.','Evolui com Pedra Água.']},
  {id:135,name:'Jolteon',types:['Electric'],desc:'Cada pelo é como uma agulha que dispara eletricidade. Acumula íons negativos para criar raios.',abilities:['Volt Absorb','Quick Feet'],stats:{hp:65,atk:65,def:60,spa:110,spd:95,spe:130},curiosities:['O Eevee mais rápido com 130 de velocidade.','Volt Absorb restaura HP ao ser atingido por elétrico.','Evolui com Pedra Trovão.']},
  {id:136,name:'Flareon',types:['Fire'],desc:'O saco de ar interno aquece o ar a 3000°C antes de ser expelido como chama.',abilities:['Flash Fire','Guts'],stats:{hp:65,atk:130,def:60,spa:95,spd:110,spe:65},curiosities:['Maior Ataque físico das Eeveelutions.','Paradoxalmente, aprende poucos golpes físicos de Fogo.','Evolui com Pedra Fogo.']},
  {id:137,name:'Porygon',types:['Normal'],desc:'O primeiro Pokémon criado inteiramente por seres humanos usando tecnologia de computador.',abilities:['Trace','Download','Analytic'],stats:{hp:65,atk:60,def:70,spa:85,spd:75,spe:40},curiosities:['Foi o Pokémon central no episódio que causou convulsões no Japão.','Único Pokémon totalmente artificial de Kanto.','Download pode aumentar Ataque ou Sp. Atk conforme o oponente.']},
  {id:138,name:'Omanyte',types:['Rock','Water'],desc:'Fóssil restaurado. Capturado em extinção há 300 milhões de anos. Nada com tentáculos.',abilities:['Swift Swim','Shell Armor','Weak Armor'],stats:{hp:35,atk:40,def:100,spa:90,spd:55,spe:35},curiosities:['Restaurado do Helix Fossil.','O meme "Lord Helix" do Twitter veio deste Pokémon.','100 de Defesa base sendo um Pokémon fóssil jovem.']},
  {id:139,name:'Omastar',types:['Rock','Water'],desc:'Os tentáculos capturam presas. A concha ficou tão grande que o tornava lento.',abilities:['Swift Swim','Shell Armor','Weak Armor'],stats:{hp:70,atk:60,def:125,spa:115,spd:70,spe:55},curiosities:['125 de Defesa e 115 de Sp. Atk — excelente combinação.','Swift Swim dobra velocidade na chuva.','Dizem que se extinguiu porque a concha era grande demais.']},
  {id:140,name:'Kabuto',types:['Rock','Water'],desc:'Fóssil há 300 milhões de anos. Os olhos vermelhos no topo veem no escuro absoluto.',abilities:['Swift Swim','Battle Armor','Weak Armor'],stats:{hp:30,atk:80,def:90,spa:55,spd:45,spe:55},curiosities:['Restaurado do Dome Fossil.','Baseado nos trilobitas extintos da era Paleozoica.','Alguns Kabuto sobreviveram e vivem no fundo do oceano.']},
  {id:141,name:'Kabutops',types:['Rock','Water'],desc:'As foices absorvem fluidos das presas. Adaptou-se para andar na terra.',abilities:['Swift Swim','Battle Armor','Weak Armor'],stats:{hp:60,atk:115,def:105,spa:65,spd:70,spe:80},curiosities:['115 de Ataque — um dos físicos mais fortes de Kanto.','Considerado mais intimidador que dinossauros fósseis.','Swift Swim + Chuva torna Kabutops devastador.']},
  {id:142,name:'Aerodactyl',types:['Rock','Flying'],desc:'Criatura pré-histórica restaurada de DNA em âmbar. Os dentes serrilhados rasgam tudo.',abilities:['Rock Head','Pressure','Unnerve'],stats:{hp:80,atk:105,def:65,spa:60,spd:75,spe:130},curiosities:['130 de velocidade — o mais rápido de Kanto exceto Mewtwo.','Tem Mega Evolução ainda mais poderosa.','Restaurado de Old Amber encontrado no Museu de Pewter.']},
  {id:143,name:'Snorlax',types:['Normal'],desc:'Muito preguiçoso. Come 400kg de comida por dia e dorme o resto.',abilities:['Immunity','Thick Fat','Gluttony'],stats:{hp:160,atk:110,def:65,spa:65,spd:110,spe:30},curiosities:['160 de HP — o maior de Kanto exceto lendários.','Bloqueia caminhos no jogo e só acorda com a Pokéflauta.','Thick Fat reduz dano de Fogo e Gelo — poucas fraquezas.']},
  {id:144,name:'Articuno',types:['Ice','Flying'],desc:'Lendário que aparece em picos nevados. Bate as asas e cria tempestades de neve.',abilities:['Pressure','Snow Cloak'],stats:{hp:90,atk:85,def:100,spa:95,spd:125,spe:85},curiosities:['O pássaro lendário de gelo de Kanto.','125 de Sp. Def — o mais alto dos três pássaros.','Encontrado nas Seafoam Islands após puzzles complexos.']},
  {id:145,name:'Zapdos',types:['Electric','Flying'],desc:'Lendário que aparece em tempestades. Raios caem onde quer que apareça.',abilities:['Pressure','Static'],stats:{hp:90,atk:90,def:85,spa:125,spd:90,spe:100},curiosities:['Considerado o mais poderoso dos três pássaros.','Static pode paralisar atacantes no contato.','Encontrado na Power Plant abandonada de Kanto.']},
  {id:146,name:'Moltres',types:['Fire','Flying'],desc:'Lendário do fogo. Quando ferido, mergulha num vulcão para curar as chamas do corpo.',abilities:['Pressure','Flame Body'],stats:{hp:90,atk:100,def:90,spa:125,spd:85,spe:90},curiosities:['Único dos três pássaros com Ataque físico relevante.','Flame Body queima atacantes no contato.','Encontrado na Vitória Road — o mais difícil de alcançar.']},
  {id:147,name:'Dratini',types:['Dragon'],desc:'Considerado mitológico por muito tempo. Habita rios com fortes correntezas.',abilities:['Shed Skin','Marvel Scale'],stats:{hp:41,atk:64,def:45,spa:50,spd:50,spe:50},curiosities:['Era considerado lendário até ser encontrado vivo.','Shed Skin tem 33% de chance de curar status por turno.','Um dos Pokémon mais cobiçados pelos treinadores.']},
  {id:148,name:'Dragonair',types:['Dragon'],desc:'Emana aura misteriosa que muda o clima. Pérolas no pescoço amplificam o poder.',abilities:['Shed Skin','Marvel Scale'],stats:{hp:61,atk:84,def:65,spa:70,spd:70,spe:70},curiosities:['Considerado o mais bonito da linha evolutiva.','As esferas controlam habilidades climáticas.','Marvel Scale aumenta Defesa quando com status.']},
  {id:149,name:'Dragonite',types:['Dragon','Flying'],desc:'Pokémon amigável que guia barcos perdidos à costa. Voa ao redor do globo em 16 horas.',abilities:['Inner Focus','Multiscale'],stats:{hp:91,atk:134,def:95,spa:100,spd:100,spe:80},curiosities:['134 de Ataque — o mais alto de toda 1ª geração não-lendária.','Multiscale reduz dano pela metade com HP cheio.','Pode voar ao redor da Terra em menos de 16 horas.']},
  {id:150,name:'Mewtwo',types:['Psychic'],desc:'O Pokémon mais poderoso. Criado por engenharia genética a partir do DNA de Mew.',abilities:['Pressure','Unnerve'],stats:{hp:106,atk:110,def:90,spa:154,spd:90,spe:130},curiosities:['154 de Sp. Atk — o maior de toda 1ª geração.','Tem duas Mega Evoluções: X (Psíquico/Lutador) e Y.','É o vilão do primeiro filme Pokémon.']},
  {id:151,name:'Mew',types:['Psychic'],desc:'Tão raro que muitos o consideravam um sonho. Contém o DNA de todos os Pokémon.',abilities:['Synchronize'],stats:{hp:100,atk:100,def:100,spa:100,spd:100,spe:100},curiosities:['Todas as estatísticas iguais a 100 — simetria perfeita.','Pode aprender qualquer TM ou HM do jogo.','Foi adicionado secretamente por Shigeki Morimoto sem que outros soubessem.']},
];
